import { loadFont as loadBarlow } from "@remotion/google-fonts/BarlowCondensed";
import { loadFont as loadVibes } from "@remotion/google-fonts/GreatVibes";
import { AbsoluteFill, Easing, Img, interpolate, OffthreadVideo, Sequence, spring, staticFile, useCurrentFrame } from "remotion";

// J. Leite (Old Dog'z), Reels da estampa SUBÚRBIO (pedido de 15/11, sem narração).
// Abre com "Subúrbio, onde o Rio é de verdade!", passa rápido pelo cotidiano do subúrbio (trem, pipa, samba e feira
// desenhados nas cores da estampa, intercalados com o bar e o brinde das fotos e vídeos do cliente), depois só a estampa:
// mockup, closes de cada parte (título, mesa, banquinhos, bairros) e a camisa nas fotos. Fecha no logo com a tela
// desligando como TV (o final de sempre da marca). Tudo cortado na batida da música do reel que o cliente mandou (94 BPM).
// Base de ritmo: Ensaio de Aniversário (fotos em batida) e NEAFH (cortes com faixa de cor, soco curto na troca).

const { fontFamily: BLOCK } = loadBarlow("normal", { weights: ["800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SCRIPT } = loadVibes("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });

export const JS_FPS = 30;
const BEAT = 0.75; // v5: BK, "Não Adianta Chorar" (80 BPM)
const B0 = 0.75; // v6: a faixa entra antes, em 26,915 s (com o trompete); a batida forte de 27,665 s cai aqui e o compasso de 30,665 s em b(4)
const b = (n: number) => B0 + n * BEAT;
const FIN = b(29); // logo
const OPEN = b(4); // fim da abertura
const OFF = FIN + 2.6; // tela desliga como TV
const DUR = OFF + 0.85;
export const JS_FRAMES = Math.round(DUR * JS_FPS);

const WHITE = "#FFFFFF";
const BLACK = "#0A0A0A";
const YELLOW = "#F4B400";
const RED = "#D3201F";
const PAPER = "#ECEBE7";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const IN = Easing.bezier(0.55, 0, 1, 0.45);
const k = (t: number, a: number, d = 0.4, ease = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: ease });
const lin = (t: number, a: number, z: number) => interpolate(t, [a, z], [0, 1], cl);
const sp = (t: number, a: number, damping = 18, stiffness = 140) =>
  t < a ? 0 : spring({ frame: (t - a) * JS_FPS, fps: JS_FPS, config: { damping, stiffness, mass: 0.8 } });

const Rise: React.FC<{ t: number; at: number; size: number; color?: string; children: string; d?: number }> = ({ t, at, size, color = WHITE, children, d = 0.32 }) => {
  const q = k(t, at, d);
  return (
    <div style={{ overflow: "hidden", paddingTop: size * 0.3, marginTop: -size * 0.24, lineHeight: 0.95 }}>
      <div style={{ fontFamily: BLOCK, fontWeight: 800, fontSize: size, color, transform: `translateY(${(1 - q) * 145}%)`, whiteSpace: "nowrap", letterSpacing: size * 0.005 }}>
        {children}
      </div>
    </div>
  );
};

// "Subúrbio" cursivo, escrito da esquerda para a direita
const Script: React.FC<{ t: number; at: number; size: number; color?: string; d?: number; children: string }> = ({ t, at, size, color = WHITE, d = 0.5, children }) => {
  const q = k(t, at, d, IN_OUT);
  return (
    <div style={{ fontFamily: SCRIPT, fontSize: size, color, lineHeight: 1.1, padding: `0 ${size * 0.25}px`, whiteSpace: "nowrap", WebkitTextStroke: `${size * 0.012}px ${color}`, clipPath: `inset(-20% ${(1 - q) * 100}% -20% 0)` }}>
      {children}
    </div>
  );
};

// foto em tela cheia; a câmera aproxima de z0 até z1 mirando (fx, fy)
const Photo: React.FC<{ file: string; w: number; h: number; fx: number; fy: number; z: number; py?: number }> = ({ file, w, h, fx, fy, z, py = 960 }) => {
  const s = Math.max(1080 / w, 1920 / h) * z;
  const W = w * s;
  const H = h * s;
  const left = Math.min(0, Math.max(1080 - W, 540 - fx * W));
  const top = Math.min(0, Math.max(1920 - H, py - fy * H));
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: BLACK }}>
      <Img src={staticFile(`j-leite/p4/${file}.jpg`)} style={{ position: "absolute", left, top, width: W, height: H }} />
    </AbsoluteFill>
  );
};

const Clip: React.FC<{ src: string; at: number; from: number; crop?: number }> = ({ src, at, from, crop = 1 }) => (
  <Sequence from={Math.round(at * JS_FPS)} layout="none">
    <OffthreadVideo src={staticFile(`j-leite/p4/${src}.mp4`)} trimBefore={Math.round(from * JS_FPS)} muted style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", transform: `scale(${crop})`, transformOrigin: "50% 100%" }} />
  </Sequence>
);

// ---------- desenhos do subúrbio (cores da estampa: amarelo da mesa, vermelho dos banquinhos, preto do traço) ----------
const STROKE = { stroke: BLACK, strokeWidth: 10, strokeLinejoin: "round" as const, strokeLinecap: "round" as const };

const Trem: React.FC<{ u: number }> = ({ u }) => {
  // o trem atravessa da direita para a esquerda; trilhos e dormentes correm por baixo
  const x = interpolate(u, [0, 1.35], [1150, -2350], { ...cl, easing: Easing.bezier(0.3, 0, 0.7, 1) });
  const sl = (u * 900) % 120;
  const car = (dx: number) => (
    <g transform={`translate(${dx},0)`} key={dx}>
      <rect x={0} y={760} width={860} height={420} rx={46} fill={WHITE} {...STROKE} />
      <rect x={0} y={1060} width={860} height={44} fill={RED} />
      {[60, 250, 440, 630].map((wx) => (
        <rect key={wx} x={wx} y={830} width={150} height={150} rx={18} fill={BLACK} />
      ))}
      <rect x={385} y={830} width={0} height={0} />
      <circle cx={170} cy={1205} r={44} fill={BLACK} />
      <circle cx={690} cy={1205} r={44} fill={BLACK} />
    </g>
  );
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute" }}>
      {/* fios de poste */}
      <path d="M -20 420 Q 540 520 1100 420" fill="none" stroke={BLACK} strokeWidth={5} />
      <path d="M -20 500 Q 540 600 1100 500" fill="none" stroke={BLACK} strokeWidth={5} />
      {/* trilhos */}
      {Array.from({ length: 12 }).map((_, i) => (
        <rect key={i} x={i * 120 - sl - 60} y={1250} width={60} height={60} fill={BLACK} />
      ))}
      <rect x={0} y={1250} width={1080} height={16} fill={BLACK} />
      <rect x={0} y={1300} width={1080} height={16} fill={BLACK} />
      <g transform={`translate(${x},0)`}>
        {car(0)}
        {car(900)}
        {car(1800)}
        <rect x={860} y={980} width={40} height={60} fill={BLACK} />
        <rect x={1760} y={980} width={40} height={60} fill={BLACK} />
      </g>
    </svg>
  );
};

const Pipa: React.FC<{ u: number }> = ({ u }) => {
  const rise = sp(u, 0, 14, 90);
  const sway = Math.sin(u * 7) * 7;
  const y = 260 + (1 - rise) * 1200;
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute" }}>
      <path d="M -20 1500 Q 540 1580 1100 1460" fill="none" stroke={BLACK} strokeWidth={5} />
      <path d="M -20 1580 Q 540 1660 1100 1540" fill="none" stroke={BLACK} strokeWidth={5} />
      <g transform={`translate(560,${y}) rotate(${sway})`}>
        <path d={`M 0 640 Q -120 900 -340 ${1500 - y}`} fill="none" stroke={BLACK} strokeWidth={4} />
        <path d="M 0 0 L 300 330 L 0 640 L -300 330 Z" fill={YELLOW} {...STROKE} />
        <path d="M 0 0 L 300 330 L 0 330 Z" fill={RED} />
        <path d="M 0 330 L -300 330 L 0 640 Z" fill={RED} />
        <path d="M 0 0 L 300 330 L 0 640 L -300 330 Z" fill="none" {...STROKE} />
        <path d="M 0 0 L 0 640 M -300 330 L 300 330" {...STROKE} />
        {/* rabiola */}
        <path d={`M 0 640 Q ${40 + sway * 4} 760 0 880 Q ${-40 - sway * 4} 1000 0 1120`} fill="none" stroke={BLACK} strokeWidth={5} />
        {[760, 880, 1000].map((ty, i) => (
          <path key={ty} d={`M -34 ${ty} L 34 ${ty + 24} L 34 ${ty - 24} L -34 ${ty} Z`} fill={i % 2 ? YELLOW : RED} stroke={BLACK} strokeWidth={5} transform={`rotate(${sway * (i + 1)} 0 ${ty})`} />
        ))}
      </g>
    </svg>
  );
};

const Pandeiro: React.FC<{ u: number }> = ({ u }) => {
  const s = sp(u, 0, 13, 160);
  const shake = Math.sin(u * 38) * 6 * Math.min(1, u * 3);
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute" }}>
      <g transform={`translate(540,880) scale(${s}) rotate(${-12 + shake})`}>
        <circle r={380} fill={BLACK} />
        <circle r={330} fill={PAPER} {...STROKE} />
        {Array.from({ length: 6 }).map((_, i) => {
          const a = (i / 6) * Math.PI * 2 + 0.25;
          return (
            <g key={i} transform={`translate(${Math.cos(a) * 356},${Math.sin(a) * 356}) rotate(${(a * 180) / Math.PI + 90})`}>
              <rect x={-48} y={-22} width={96} height={44} rx={8} fill={YELLOW} {...STROKE} strokeWidth={7} />
            </g>
          );
        })}
        <circle r={110} fill="none" stroke={RED} strokeWidth={18} />
      </g>
      {/* traços de batida */}
      {[0, 1, 2].map((i) => {
        const o = Math.max(0, Math.sin(u * 19 + i));
        return <path key={i} d={`M ${920 + i * 22} ${560 + i * 70} l 70 -40`} stroke={BLACK} strokeWidth={10} strokeLinecap="round" opacity={o} />;
      })}
      {[0, 1, 2].map((i) => {
        const o = Math.max(0, Math.sin(u * 19 + i + 1.5));
        return <path key={`l${i}`} d={`M ${160 - i * 22} ${1160 + i * 70} l -70 40`} stroke={BLACK} strokeWidth={10} strokeLinecap="round" opacity={o} />;
      })}
    </svg>
  );
};

const Feira: React.FC<{ u: number }> = ({ u }) => {
  const drop = sp(u, 0, 15, 150);
  const pops = [0.12, 0.18, 0.24, 0.3, 0.36];
  const fruit = (i: number, cx: number, cy: number, r: number, fill: string) => {
    const s = sp(u, pops[i], 12, 200);
    return <circle key={i} cx={cx} cy={cy} r={r * s} fill={fill} {...STROKE} strokeWidth={8} />;
  };
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute" }}>
      {/* toldo listrado que desce */}
      <g transform={`translate(0,${(drop - 1) * 700})`}>
        <rect x={100} y={420} width={880} height={160} fill={WHITE} {...STROKE} />
        {Array.from({ length: 8 }).map((_, i) => (
          <rect key={i} x={100 + i * 110} y={420} width={55} height={160} fill={RED} />
        ))}
        <path d={`M 100 580 ${Array.from({ length: 8 }).map((_, i) => `Q ${155 + i * 110} 680 ${210 + i * 110} 580`).join(" ")}`} fill={RED} {...STROKE} />
        <rect x={100} y={420} width={880} height={160} fill="none" {...STROKE} />
      </g>
      {/* mastros e banca */}
      <rect x={130} y={600} width={26} height={760} fill={BLACK} />
      <rect x={924} y={600} width={26} height={760} fill={BLACK} />
      <rect x={110} y={1180} width={860} height={70} fill={YELLOW} {...STROKE} />
      <rect x={150} y={1250} width={780} height={150} fill={BLACK} />
      {fruit(0, 260, 1110, 70, "#F28C28")}
      {fruit(1, 410, 1100, 80, "#F28C28")}
      {fruit(2, 570, 1110, 70, "#F28C28")}
      {fruit(3, 720, 1100, 80, "#F28C28")}
      {fruit(4, 860, 1110, 66, "#F28C28")}
      {/* melancia em fatia */}
      <g transform={`translate(540,${960 + (1 - sp(u, 0.42, 12, 180)) * 900})`}>
        <path d="M -200 0 A 200 200 0 0 0 200 0 Z" fill="#2E7D32" {...STROKE} />
        <path d="M -170 0 A 170 170 0 0 0 170 0 Z" fill={RED} />
        {[-90, -30, 30, 90].map((sx) => (
          <ellipse key={sx} cx={sx} cy={60} rx={9} ry={15} fill={BLACK} />
        ))}
        <path d="M -200 0 L 200 0" {...STROKE} />
      </g>
    </svg>
  );
};

// ---------- cenas ----------
type Enter = "punch" | "left" | "up" | "iris" | "wipe" | "split" | "zoom" | "fade";
type Scene =
  | { kind: "photo"; at: number; len: number; file: string; w?: number; h?: number; fx: number; fy: number; z0?: number; z1?: number; enter: Enter; dark?: number }
  | { kind: "clip"; at: number; len: number; src: string; from: number; enter: Enter; crop?: number }
  | { kind: "draw"; at: number; len: number; art: "trem" | "pipa" | "pandeiro" | "feira"; bg: string; enter: Enter }
  | { kind: "mock"; at: number; len: number; mock: string; bg: string; enter: Enter; mw?: number }
  | { kind: "cut"; at: number; len: number; mock: string; bgs: Bg[]; step?: number; enter: Enter };
type Bg = { file: string; fx: number; fy: number; z: number };

