const enterStyle = (e: Enter, q: number): React.CSSProperties => {
  if (e === "fade") return { opacity: q, mixBlendMode: q < 0.999 ? "screen" : "normal" };
  if (e === "iris") return { clipPath: `circle(${q * 125}% at 50% 50%)` };
  if (e === "up") return { transform: `translateY(${(1 - q) * 1920}px)` };
  if (e === "left") return { transform: `translateX(${(1 - q) * 1080}px)` };
  if (e === "wipe") return { clipPath: `inset(0 0 0 ${(1 - q) * 100}%)` };
  if (e === "split") return { clipPath: `inset(0 ${(1 - q) * 50}% 0 ${(1 - q) * 50}%)` };
  if (e === "zoom") return { clipPath: `inset(${(1 - q) * 50}% ${(1 - q) * 50}% ${(1 - q) * 50}% ${(1 - q) * 50}%)` };
  return {};
};

const SceneView: React.FC<{ t: number; s: Scene }> = ({ t, s }) => {
  const a = b(s.at);
  const z = b(s.at + s.len);
  if (t < a - 0.01 || t >= z + 0.3) return null;
  const u = t - a;
  const fd = Math.min(0.24, s.len * BEAT * 0.55);
  const q = s.enter === "punch" ? 1 : s.enter === "fade" ? k(u, 0, fd, IN_OUT) : k(u, 0, 0.26, IN_OUT);
  const punch = s.enter === "punch" ? 1 + 0.12 * (1 - k(u, 0, 0.28)) : 1;
  const p = lin(t, a, z + 0.3);
  let body: React.ReactNode = null;
  if (s.kind === "photo") {
    const z0 = s.z0 ?? 1.04;
    const z1 = s.z1 ?? 1.12;
    body = (
      <>
        <Photo file={s.file} w={s.w ?? PH.w} h={s.h ?? PH.h} fx={s.fx} fy={s.fy} z={z0 + (z1 - z0) * p} />
        {s.dark ? <AbsoluteFill style={{ background: `rgba(0,0,0,${s.dark})` }} /> : null}
      </>
    );
  } else if (s.kind === "clip") {
    body = (
      <AbsoluteFill style={{ background: BLACK, transform: `scale(${1.02 + 0.06 * p})` }}>
        <Clip src={s.src} at={a} from={s.from} crop={s.crop} />
      </AbsoluteFill>
    );
  } else if (s.kind === "draw") {
    const Art = { trem: Trem, pipa: Pipa, pandeiro: Pandeiro, feira: Feira }[s.art];
    body = (
      <AbsoluteFill style={{ background: s.bg, transform: `scale(${1 + 0.04 * p})` }}>
        <Art u={u} />
      </AbsoluteFill>
    );
  } else if (s.kind === "mock") {
    const m = sp(u, 0.04, 16, 150);
    body = (
      <AbsoluteFill style={{ background: s.bg }}>
        <Img
          src={staticFile(`j-leite/p4/${s.mock}.png`)}
          style={{ position: "absolute", width: s.mw ?? 1500, left: 540 - (s.mw ?? 1500) / 2, top: 900 - ((s.mw ?? 1500) * 1032) / 1600 / 2, transform: `translateY(${(1 - m) * 500}px) scale(${(0.9 + 0.1 * m) * (1 + 0.05 * p)})`, filter: `drop-shadow(0 30px 40px rgba(0,0,0,${s.bg === BLACK ? 0.6 : 0.25}))` }}
        />
      </AbsoluteFill>
    );
  } else if (s.kind === "cut") {
    const step = (s.step ?? 0.5) * BEAT;
    const i = Math.min(s.bgs.length - 1, Math.floor(Math.max(0, u) / step));
    const ui = u - i * step;
    const bg = s.bgs[i];
    const m = sp(u, 0.02, 15, 170);
    const hit = 1 + 0.05 * (1 - k(ui, 0, 0.22));
    body = (
      <AbsoluteFill style={{ background: BLACK }}>
        <AbsoluteFill style={{ transform: `scale(${hit})`, filter: "blur(3px) brightness(0.62)" }}>
          <Photo file={bg.file} w={PH.w} h={PH.h} fx={bg.fx} fy={bg.fy} z={bg.z * (1 + 0.04 * p)} />
        </AbsoluteFill>
        <Img
          src={staticFile(`j-leite/p4/${s.mock}.png`)}
          style={{ position: "absolute", width: 1500, left: -210, top: 900 - (1500 * 1032) / 1600 / 2, transform: `translateY(${(1 - m) * 420}px) rotate(${(1 - m) * -8 + (i % 2 ? 1.2 : -1.2) * (1 - k(ui, 0, 0.25))}deg) scale(${(0.9 + 0.1 * m) * (1 + 0.04 * p)})`, filter: "drop-shadow(0 34px 44px rgba(0,0,0,0.6))" }}
        />
      </AbsoluteFill>
    );
  }
  return (
    <AbsoluteFill style={enterStyle(s.enter, q)}>
      <AbsoluteFill style={{ transform: `scale(${punch})` }}>{body}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// abertura (ref. foto-1, Marathon / Fear of God): o "Subúrbio" da própria arte, grande no meio, e a frase pequena
// embaixo, sobre o subúrbio de verdade trocando a cada meia batida
const OPEN_BG: { src: string; from: number; crop?: number }[] = [
  { src: "d6", from: 4.0 },
  { src: "d3", from: 0.6 },
  { src: "d5", from: 30.8 },
  { src: "d4", from: 0.5 },
  { src: "d2", from: 4.8, crop: 1.32 },
  { src: "d6", from: 13.0 },
  { src: "d5", from: 13.4 },
  { src: "d4", from: 22.4 },
];
const TYPE = "ONDE O RIO É DE VERDADE";
export const TYPE_AT = 1.3; // começa na pausa da faixa (28,25–29,25 s)
export const TYPE_STEP = 0.05;
const Abertura: React.FC<{ t: number }> = ({ t }) => {
  const step = BEAT / 2;
  const i = Math.max(0, Math.min(OPEN_BG.length - 1, Math.floor((t - B0) / step)));
  const ui = t - B0 - i * step;
  const out = k(t, OPEN - 0.22, 0.24, IN);
  const title = k(t, B0 - 0.5, 0.5, IN_OUT);
  const titleS = 1.12 - 0.12 * k(t, B0 - 0.5, 0.6) + 0.025 * lin(t, B0, OPEN);
  const hit = 1 + 0.06 * (1 - k(Math.max(0, ui), 0, 0.22));
  // a frase embaixo é digitada, letra a letra, na pausa da música
  const typed = Math.max(0, Math.min(TYPE.length, Math.floor((t - TYPE_AT) / TYPE_STEP) + 1));
  const caret = t >= TYPE_AT - 0.2 && (typed < TYPE.length || Math.floor(t * 2.5) % 2 === 0);
  const bg = OPEN_BG[i];
  return (
    <AbsoluteFill style={{ background: BLACK, opacity: 1 - out }}>
      <AbsoluteFill key={i} style={{ transform: `scale(${hit * (1 + 0.04 * lin(t, 0, OPEN))})`, filter: "brightness(0.5) saturate(0.85)" }}>
        <Clip src={bg.src} at={i === 0 ? 0 : B0 + i * step} from={i === 0 ? Math.max(0, bg.from - B0) : bg.from} crop={bg.crop} />
      </AbsoluteFill>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 48%, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.55) 70%)" }} />
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", paddingBottom: 80 }}>
        <Img src={staticFile("j-leite/p4/titulo-arte.png")} style={{ width: 800, transform: `scale(${titleS})`, clipPath: `inset(-10% ${(1 - title) * 100}% -10% 0)`, filter: "drop-shadow(0 6px 22px rgba(0,0,0,0.55))" }} />
        <div style={{ marginTop: 34, fontFamily: BLOCK, fontWeight: 800, fontSize: 58, letterSpacing: 9, color: WHITE, textShadow: "0 3px 14px rgba(0,0,0,0.6)", whiteSpace: "pre" }}>
          {TYPE.slice(0, typed)}
          <span style={{ position: "relative", display: "inline-block", width: 0, height: 58, verticalAlign: "top" }}>
            {caret ? <span style={{ position: "absolute", left: -2, top: 8, width: 5, height: 52, background: YELLOW }} /> : null}
          </span>
          <span style={{ color: "transparent", textShadow: "none" }}>{TYPE.slice(typed)}</span>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

const Final: React.FC<{ t: number }> = ({ t }) => {
  const s = sp(t, FIN + 0.1, 15, 150);
  const cam = 1 + 0.05 * lin(t, FIN, DUR);
  return (
    <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", transform: `scale(${cam})` }}>
      <Img src={staticFile("j-leite/logo-od-branco.png")} style={{ width: 760, transform: `scale(${0.7 + 0.3 * s})`, opacity: Math.min(1, s * 1.6) }} />
    </AbsoluteFill>
  );
};

export const JLeiteSuburbio: React.FC = () => {
  const t = useCurrentFrame() / JS_FPS;
  const blk = k(t, FIN - 0.05, 0.36);
  const sy = interpolate(t, [OFF, OFF + 0.17], [1, 0.004], { ...cl, easing: Easing.bezier(0.6, 0, 0.9, 0.3) });
  const sx = interpolate(t, [OFF + 0.17, OFF + 0.36], [1, 0.006], { ...cl, easing: Easing.bezier(0.5, 0, 0.8, 0.4) });
  const burn = interpolate(t, [OFF, OFF + 0.17], [0, 1], cl);
  const dot = interpolate(t, [OFF + 0.32, OFF + 0.48], [1, 0], cl);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <AbsoluteFill style={{ transform: `scale(${sx}, ${sy})`, opacity: dot, filter: `brightness(${1 + burn * 1.6})`, overflow: "hidden", background: BLACK }}>
        {SCENES.map((s) => (
          <SceneView key={`${s.kind}-${s.at}`} t={t} s={s} />
        ))}
        {t < OPEN + 0.1 ? <Abertura t={t} /> : null}
        {t >= FIN - 0.05 ? (
          <AbsoluteFill style={{ background: BLACK, clipPath: `inset(0 0 ${(1 - blk) * 100}% 0)` }}>
            <Final t={t} />
          </AbsoluteFill>
        ) : null}
      </AbsoluteFill>
      {t >= OFF + 0.17 && t < OFF + 0.5 ? (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
          <div style={{ width: 1080 * sx + 6, height: 8, borderRadius: 8, background: WHITE, opacity: dot, boxShadow: "0 0 24px rgba(255,255,255,0.8)" }} />
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

